
const COMPOUND_SEPARATOR = /\s*[—–]\s*|\s+-\s+/;

const asSentence = (fragment: string): string => {
  const capitalized = fragment[0].toUpperCase() + fragment.slice(1);
  return /[.!?]$/.test(capitalized) ? capitalized : `${capitalized}.`;
};

export const normalizeBriefContent = <
  T extends { label: string; body: string },
>(
  brief: T,
): T => {
  const label = brief.label.trim();
  const parts = label.split(COMPOUND_SEPARATOR);
  if (parts.length < 2) {
    return label === brief.label ? brief : { ...brief, label };
  }

  const head = parts[0].trim();
  const tail = parts.slice(1).join(' ').trim();
  if (!head || !tail) {
    return { ...brief, label };
  }

  const body = brief.body.trim();
  const bodyAlreadyCoversTail = body
    .toLowerCase()
    .includes(tail.toLowerCase());
  const mergedBody =
    !body || bodyAlreadyCoversTail
      ? body || asSentence(tail)
      : `${asSentence(tail)} ${body}`;

  return { ...brief, label: head, body: mergedBody };
};
